class InspectorUnitProbeFixture {
  private InspectorUnitProbeFixture() {}

  static final class Script implements InspectorUnitProbe.Reader {
    final List<String> calls = new ArrayList<>();
    final List<byte[]> delivered = new ArrayList<>();
    List<String> states = List.of(GOLDEN, GOLDEN);
    byte[] processes = "a(sus) 0\n".getBytes(StandardCharsets.US_ASCII);
    int stateAt;
    int failAt;
    int nullAt;
    int interruptAt;
    RuntimeException runtime;

    private byte[] next(String type, byte[] bytes) throws IOException {
      calls.add(type);
      if (calls.size() == interruptAt) Thread.currentThread().interrupt();
      if (calls.size() == failAt) {
        if (runtime != null) throw runtime;
        throw new IOException("PUBLIC_DIAGNOSTIC_CANARY");
      }
      if (calls.size() == nullAt) return null;
      byte[] result = bytes.clone();
      delivered.add(result);
      return result;
    }

    @Override
    public byte[] readState() throws IOException {
      return next(
          "state",
          states.get(Math.min(stateAt++, states.size() - 1)).getBytes(StandardCharsets.US_ASCII));
    }

    @Override
    public byte[] readProcesses() throws IOException {
      return next("processes", processes);
    }

    void wiped() {
      for (byte[] bytes : delivered) assertArrayEquals(new byte[bytes.length], bytes);
    }
  }

  static final class Child extends Process {
    final ReadStream output;
    final ReadStream error;
    final WriteStream input;
    final Map<String, Integer> counts = new LinkedHashMap<>();
    final List<String> order = new ArrayList<>();
    final Set<String> ioFailures = new HashSet<>();
    BiConsumer<String, Integer> hook = (name, count) -> {};
    boolean completed = true;
    boolean waitInterrupt;
    boolean alive = true;
    long waitSeconds = 5;
    String missing = "";
    int code;
    int destroyed;
    byte[] delivered = new byte[0];

    Child(byte[] bytes) {
      output = new ReadStream("stdout", bytes);
      error = new ReadStream("stderr", new byte[0]);
      input = new WriteStream();
    }

    void event(String name) {
      order.add(name);
      hook.accept(name, counts.merge(name, 1, Integer::sum));
    }

    void io(String name) throws IOException {
      event(name);
      if (ioFailures.contains(name)) throw new IOException("PUBLIC_DIAGNOSTIC_CANARY");
    }

    @Override
    public InputStream getInputStream() {
      event("get.stdout");
      return missing.equals("stdout") ? null : output;
    }

    @Override
    public OutputStream getOutputStream() {
      event("get.stdin");
      return missing.equals("stdin") ? null : input;
    }

    @Override
    public InputStream getErrorStream() {
      event("get.stderr");
      return missing.equals("stderr") ? null : error;
    }

    @Override
    public int waitFor() {
      throw new AssertionError("unbounded wait forbidden");
    }

    @Override
    public boolean waitFor(long timeout, TimeUnit unit) throws InterruptedException {
      assertEquals(waitSeconds, timeout);
      assertEquals(TimeUnit.SECONDS, unit);
      event("wait");
      if (waitInterrupt) throw new InterruptedException("PUBLIC_DIAGNOSTIC_CANARY");
      alive = !completed;
      return completed;
    }

    @Override
    public int exitValue() {
      event("exit");
      assertFalse(alive);
      return code;
    }

    @Override
    public boolean isAlive() {
      event("alive");
      return alive;
    }

    @Override
    public void destroy() {
      destroyed++;
      alive = false;
      event("destroy");
    }

    @Override
    public Process destroyForcibly() {
      throw new AssertionError("SIGKILL forbidden");
    }

    void allClosed() {
      assertEquals(1, output.closed);
      assertEquals(1, input.closed);
      assertEquals(1, error.closed);
    }

    void wiped() {
      assertArrayEquals(new byte[delivered.length], delivered);
    }

    final class ReadStream extends InputStream {
      final String name;
      final byte[] bytes;
      int closed;
      int maximum;
      boolean nullRead;

      ReadStream(String name, byte[] bytes) {
        this.name = name;
        this.bytes = bytes.clone();
      }

      @Override
      public int read() {
        throw new AssertionError("bounded bulk reads only");
      }

      @Override
      public byte[] readNBytes(int limit) throws IOException {
        maximum = limit;
        io(name + ".read");
        if (nullRead) return null;
        delivered = Arrays.copyOf(bytes, Math.min(bytes.length, limit));
        return delivered;
      }

      @Override
      public void close() throws IOException {
        closed++;
        io(name + ".close");
      }
    }

    final class WriteStream extends OutputStream {
      int closed;

      @Override
      public void write(int value) {
        throw new AssertionError("queries accept no input");
      }

      @Override
      public void close() throws IOException {
        closed++;
        io("stdin.close");
      }
    }
  }
}

class TestIo implements InspectorCredentialLoader.Io {
    final InspectorCredentialLoader.NioIo actual = new InspectorCredentialLoader.NioIo();
    String fault = "";
    String securityFault = "";
    int rootAttributes;
    int fileAttributes;
    int opens;
    int reads;
    int closes;
    int fileNative;
    int rootRo;
    int fileRo;
    int maxRead = 70;
    Consumer<Map<String, Object>> rootChange = (a) -> {};
    Consumer<Map<String, Object>> fileChange = (a) -> {};
    Consumer<Map<String, Object>> lateRootChange = (a) -> {};
    Consumer<Map<String, Object>> lateFileChange = (a) -> {};
    Hook beforeRead = () -> {};
    final List<byte[]> buffers = new ArrayList<>();
    byte[] observedContent = new byte[0];

    @Override
    public Map<String, Object> attributes(Path held) throws IOException {
      Map<String, Object> map = new HashMap<>(actual.attributes(held));
      boolean directory = ((Integer) map.get("mode") & 0170000) == 040000;
      if (directory) {
        rootAttributes++;
        if (fault.equals("attributes-root") || fault.equals("root-final") && rootAttributes > 1)
          throw new IOException(SENTINEL);
      } else {
        fileAttributes++;
        if (fault.equals("file-missing")
            || fault.equals("file-missing-after") && fileAttributes > 1)
          throw new NoSuchFileException(SENTINEL);
        if (fault.equals("attributes-file")) throw new IOException(SENTINEL);
        if (fault.equals("null-file-map")) return null; // deliberately broken boundary result
      }
      // Explicit OS metadata seam; never claims this nonprivileged fixture is root-owned.
      map.put("uid", 0);
      map.put("mode", ((Integer) map.get("mode") & 0170000) | (directory ? 0550 : 0440));
      (directory ? rootChange : fileChange).accept(map);
      if (directory && rootAttributes > 1) lateRootChange.accept(map);
      if (!directory && fileAttributes > 1) lateFileChange.accept(map);
      return map;
    }

    @Override
    public SeekableByteChannel openReadOnly(Path held) throws IOException {
      if (fault.equals("open")) throw new IOException(SENTINEL);
      if (fault.equals("unsupported")) throw new UnsupportedOperationException(SENTINEL);
      SeekableByteChannel delegate = actual.openReadOnly(held);
      opens++;
      return new SeekableByteChannel() {
        int sizes;

        @Override
        public int read(ByteBuffer buffer) throws IOException {
          buffers.add(buffer.array());
          if (reads++ == 0) beforeRead.run();
          switch (fault) {
            case "read":
              throw new IOException(SENTINEL);
            case "short":
              return -1;
            case "zero":
              return 0;
            case "negative-read":
              return -2;
            case "lying-read":
              return 1;
            case "huge-read":
              return Integer.MAX_VALUE;
            case "long":
              while (buffer.hasRemaining()) buffer.put((byte) 'X');
              return 70;
            default:
              break;
          }
          int originalLimit = buffer.limit();
          int start = buffer.position();
          buffer.limit(Math.min(originalLimit, start + maxRead));
          int count;
          try {
            count = delegate.read(buffer);
          } finally {
            buffer.limit(originalLimit);
          }
          if (count > 0 && start == 0) observedContent = Arrays.copyOf(buffer.array(), count);
          return count;
        }

        @Override
        public long size() throws IOException {
          sizes++;
          if (fault.equals(sizes == 1 ? "size-error-before" : "size-error-after"))
            throw new IOException(SENTINEL);
          long size = delegate.size();
          return fault.equals(sizes == 1 ? "size-before" : "size-after") ? size + 1 : size;
        }

        @Override
        public void close() throws IOException {
          delegate.close();
          closes++;
          if (fault.equals("close")) throw new IOException(SENTINEL);
          if (fault.equals("close-missing")) throw new NoSuchFileException(SENTINEL);
        }

        @Override
        public boolean isOpen() {
          return delegate.isOpen();
        }

        @Override
        public long position() throws IOException {
          return delegate.position();
        }

        @Override
        public SeekableByteChannel position(long position) {
          throw new AssertionError("no seek");
        }

        @Override
        public int write(ByteBuffer source) {
          throw new AssertionError("read only");
        }

        @Override
        public SeekableByteChannel truncate(long size) {
          throw new AssertionError("read only");
        }
      };
    }

    void assertCleared() {
      assertCleared(70);
    }

    void assertCleared(int expectedSize) {
      for (byte[] buffer : buffers) assertArrayEquals(new byte[expectedSize], buffer);
      Arrays.fill(observedContent, (byte) 0); // test-owned observation is cleared as well
    }
  }

class TestSecurity implements InodeSecurityCalls {
    final TestIo io;
    long uid = 1000;

    TestSecurity(TestIo io) {
      this.io = io;
    }

    @Override
    public long effectiveUid() {
      return uid;
    }

    @Override
    public boolean readOnlyFilesystem(Path held) throws StorageIoException {
      boolean directory = Files.isDirectory(held);
      int count;
      if (directory) count = ++io.rootRo;
      else {
        count = ++io.fileRo;
        io.fileNative++;
      }
      String kind = directory ? "root" : "file";
      if (io.securityFault.equals("ro-" + kind))
        throw new StorageIoException(StorageIoException.Reason.UNAVAILABLE);
      return io.securityFault.equals("ro-" + kind + "-after") && count > 1;
    }

    @Override
    public byte[] accessAcl(Path held, int maximumBytes) throws StorageIoException {
      assertEquals(44, maximumBytes);
      boolean directory = Files.isDirectory(held);
      String kind = directory ? "root" : "file";
      int count = directory ? io.rootRo : io.fileRo;
      if (io.securityFault.equals("acl-" + kind))
        throw new StorageIoException(StorageIoException.Reason.UNAVAILABLE);
      if (io.securityFault.equals("empty-acl-" + kind)
          || io.securityFault.equals("empty-acl-" + kind + "-after") && count > 1)
        return new byte[0];
      byte[] acl =
          HexFormat.of()
              .parseHex(
                  "0200000001000400ffffffff02000400e803000004000000ffffffff10000400ffffffff20000000ffffffff");
      if (directory) for (int index : new int[] {6, 14, 30}) acl[index] = 5;
      return acl;
    }
  }
